alter table public.fju_campeonatos_times add column if not exists capitao_email text,add column if not exists link_time_hash text,add column if not exists team_email_sent_at timestamptz;
create unique index if not exists teams_shared_hash_unique on public.fju_campeonatos_times(link_time_hash) where link_time_hash is not null;
create or replace function public.fju_campeonato_criar_time_link(p_campeonato_id uuid,p_polo_id uuid,p_nome_time text,p_nome_capitao text,p_email_capitao text,p_nascimento_capitao date,p_cidade_capitao text,p_foto_capitao_path text,p_link_time_hash text,p_token_capitao_hash text,p_consent boolean) returns uuid language plpgsql security definer set search_path=''
as $$declare v_id uuid;v_today date;begin
v_today:=timezone('Asia/Tokyo',now())::date;
if p_consent is not true or p_link_time_hash!~'^[a-f0-9]{64}$' or p_token_capitao_hash!~'^[a-f0-9]{64}$' or length(trim(p_nome_time)) not between 2 and 80 or length(trim(p_nome_capitao)) not between 2 and 100 or p_email_capitao!~*'^[^@]+@[^@]+\.[^@]+$' or p_nascimento_capitao is null or p_nascimento_capitao>v_today or length(trim(p_cidade_capitao)) not between 2 and 160 then raise exception 'Dados inválidos';end if;
if p_foto_capitao_path<>p_token_capitao_hash||'/foto.jpg' or not exists(select 1 from storage.objects where bucket_id='fju-campeonato-jogadores' and name=p_foto_capitao_path) then raise exception 'Foto obrigatória';end if;
if not exists(select 1 from public.fju_campeonatos where id=p_campeonato_id and publicado and inscricoes_abertas and (prazo_inscricao is null or prazo_inscricao>=v_today)) then raise exception 'Inscrições fechadas';end if;
if not exists(select 1 from public.fju_polos where id=p_polo_id and ativo) then raise exception 'Polo inválido';end if;
insert into public.fju_campeonatos_times(campeonato_id,polo_id,nome_time,capitao_nome,capitao_email,token_capitao_hash,link_time_hash,status) values(p_campeonato_id,p_polo_id,trim(p_nome_time),trim(p_nome_capitao),lower(trim(p_email_capitao)),p_token_capitao_hash,p_link_time_hash,'pendente') returning id into v_id;
insert into public.fju_campeonatos_jogadores(time_id,token_inscricao_hash,nome,nascimento,cidade_bairro,foto_path,status,enviado_em,consent_confirmed_at) values(v_id,p_token_capitao_hash,trim(p_nome_capitao),p_nascimento_capitao,trim(p_cidade_capitao),p_foto_capitao_path,'pendente',now(),now());return v_id;end $$;
create or replace function public.fju_campeonato_time_por_link(p_link_time_hash text) returns jsonb language sql security definer set search_path='' as $$select jsonb_build_object('id',t.id,'nome',t.nome_time,'capitao',t.capitao_nome,'evento',c.titulo,'modalidade',c.modalidade,'max',c.max_jogadores_time,'inscricoes_abertas',c.inscricoes_abertas,'jogadores',(select coalesce(jsonb_agg(jsonb_build_object('nome',j.nome,'status',j.status)),'[]'::jsonb) from public.fju_campeonatos_jogadores j where j.time_id=t.id and j.status<>'rejeitado')) from public.fju_campeonatos_times t join public.fju_campeonatos c on c.id=t.campeonato_id where t.link_time_hash=p_link_time_hash and t.status<>'rejeitado'$$;
create or replace function public.fju_campeonato_cadastrar_jogador_link(p_link_time_hash text,p_token_jogador_hash text,p_nome text,p_nascimento date,p_cidade_bairro text,p_foto_path text,p_consent boolean) returns boolean language plpgsql security definer set search_path='' as $$declare v_time uuid;v_max integer;v_count integer;v_today date;begin
v_today:=timezone('Asia/Tokyo',now())::date;if p_consent is not true or p_link_time_hash!~'^[a-f0-9]{64}$' or p_token_jogador_hash!~'^[a-f0-9]{64}$' or length(trim(p_nome)) not between 2 and 100 or p_nascimento is null or p_nascimento>v_today or length(trim(p_cidade_bairro)) not between 2 and 160 then raise exception 'Dados inválidos';end if;
if p_foto_path<>p_token_jogador_hash||'/foto.jpg' or not exists(select 1 from storage.objects where bucket_id='fju-campeonato-jogadores' and name=p_foto_path) then raise exception 'Foto obrigatória';end if;
select t.id,c.max_jogadores_time into v_time,v_max from public.fju_campeonatos_times t join public.fju_campeonatos c on c.id=t.campeonato_id where t.link_time_hash=p_link_time_hash and t.status<>'rejeitado' and c.publicado and c.inscricoes_abertas and (c.prazo_inscricao is null or c.prazo_inscricao>=v_today) for update;if v_time is null then raise exception 'Link inválido/inscrições fechadas';end if;
select count(*) into v_count from public.fju_campeonatos_jogadores where time_id=v_time and status<>'rejeitado';if v_count>=v_max then raise exception 'Limite de atletas atingido';end if;
insert into public.fju_campeonatos_jogadores(time_id,token_inscricao_hash,nome,nascimento,cidade_bairro,foto_path,status,enviado_em,consent_confirmed_at) values(v_time,p_token_jogador_hash,trim(p_nome),p_nascimento,trim(p_cidade_bairro),p_foto_path,'pendente',now(),now());return true;end $$;
revoke all on function public.fju_campeonato_criar_time_link(uuid,uuid,text,text,text,date,text,text,text,text,boolean) from public,anon,authenticated;grant execute on function public.fju_campeonato_criar_time_link(uuid,uuid,text,text,text,date,text,text,text,text,boolean) to anon,authenticated;
revoke all on function public.fju_campeonato_time_por_link(text) from public,authenticated;grant execute on function public.fju_campeonato_time_por_link(text) to anon;
revoke all on function public.fju_campeonato_cadastrar_jogador_link(text,text,text,date,text,text,boolean) from public,authenticated;grant execute on function public.fju_campeonato_cadastrar_jogador_link(text,text,text,date,text,text,boolean) to anon;